use std::ops::RangeInclusive;

use serde_json::{Map, Value};

use crate::error::{Error, ErrorCode, Result};

/// Typed access to the members of a JSON object. A `null` member counts as absent.
#[derive(Clone, Copy)]
pub struct Params<'a>(&'a Map<String, Value>);

fn invalid(name: &str, wanted: &str) -> Error {
    Error::new(ErrorCode::InvalidParameterValue, format!("{name} must be {wanted}"))
}

impl<'a> Params<'a> {
    pub fn new(map: &'a Map<String, Value>) -> Self {
        Self(map)
    }

    fn get(&self, name: &str) -> Option<&'a Value> {
        self.0.get(name).filter(|value| !value.is_null())
    }

    pub fn names(&self) -> impl Iterator<Item = &'a str> + use<'a> {
        let map = self.0;
        map.iter().filter(|(_, v)| !v.is_null()).map(|(k, _)| k.as_str())
    }

    pub fn require(&self, names: &[&str]) -> Result<()> {
        match names.iter().find(|name| self.get(name).is_none()) {
            Some(name) => Err(Error::new(ErrorCode::MissingParameter, format!("{name} is required"))),
            None => Ok(()),
        }
    }

    pub fn string(&self, name: &str) -> Result<Option<&'a str>> {
        self.get(name)
            .map(|v| v.as_str().ok_or_else(|| invalid(name, "a string")))
            .transpose()
    }

    pub fn required_string(&self, name: &str) -> Result<&'a str> {
        self.string(name)?
            .ok_or_else(|| Error::new(ErrorCode::MissingParameter, format!("{name} is required")))
    }

    pub fn integer(&self, name: &str, range: RangeInclusive<u32>) -> Result<Option<u32>> {
        self.get(name)
            .map(|v| {
                v.as_i64()
                    .and_then(|n| u32::try_from(n).ok())
                    .filter(|n| range.contains(n))
                    .ok_or_else(|| {
                        invalid(name, &format!("an integer from {} to {}", range.start(), range.end()))
                    })
            })
            .transpose()
    }

    pub fn required_integer(&self, name: &str, range: RangeInclusive<u32>) -> Result<u32> {
        self.integer(name, range)?
            .ok_or_else(|| Error::new(ErrorCode::MissingParameter, format!("{name} is required")))
    }

    pub fn boolean(&self, name: &str) -> Result<Option<bool>> {
        self.get(name)
            .map(|v| v.as_bool().ok_or_else(|| invalid(name, "a boolean")))
            .transpose()
    }

    pub fn object(&self, name: &str) -> Result<Option<&'a Map<String, Value>>> {
        self.get(name)
            .map(|v| v.as_object().ok_or_else(|| invalid(name, "an object")))
            .transpose()
    }
}
