use serde_json::{Map, Value};

use crate::error::{Error, ErrorCode, Result};
use crate::params::Params;

const ATTRIBUTE_NAMES: [&str; 7] = [
    "VisibilityTimeout",
    "DelaySeconds",
    "RetentionSeconds",
    "Fifo",
    "ContentBasedDeduplication",
    "DeadLetterQueue",
    "MaxReceiveCount",
];

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum QueueKind {
    Standard,
    Fifo { content_based_dedup: bool },
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DeadLetter {
    pub queue: String,
    pub max_receive_count: u32,
}

/// The complete, valid attribute set of a queue.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct QueueConfig {
    pub visibility_timeout_secs: u32,
    pub delay_secs: u32,
    pub retention_secs: u32,
    pub kind: QueueKind,
    pub dead_letter: Option<DeadLetter>,
}

/// Attributes as given in a request; every one is optional and individually valid.
#[derive(Debug, Default)]
pub struct Attributes<'a> {
    visibility_timeout_secs: Option<u32>,
    delay_secs: Option<u32>,
    retention_secs: Option<u32>,
    fifo: Option<bool>,
    content_based_dedup: Option<bool>,
    dead_letter_queue: Option<&'a str>,
    max_receive_count: Option<u32>,
}

fn invalid(message: &str) -> Error {
    Error::new(ErrorCode::InvalidParameterValue, message)
}

impl<'a> Attributes<'a> {
    pub fn parse(map: &'a Map<String, Value>) -> Result<Self> {
        let params = Params::new(map);
        if let Some(name) = params.names().find(|name| !ATTRIBUTE_NAMES.contains(name)) {
            return Err(invalid(&format!("unknown attribute {name}")));
        }
        Ok(Self {
            visibility_timeout_secs: params.integer("VisibilityTimeout", 0..=43_200)?,
            delay_secs: params.integer("DelaySeconds", 0..=900)?,
            retention_secs: params.integer("RetentionSeconds", 60..=1_209_600)?,
            fifo: params.boolean("Fifo")?,
            content_based_dedup: params.boolean("ContentBasedDeduplication")?,
            dead_letter_queue: params.string("DeadLetterQueue")?,
            max_receive_count: params.integer("MaxReceiveCount", 1..=1000)?,
        })
    }

    pub fn fifo(&self) -> Option<bool> {
        self.fifo
    }

    pub fn dead_letter_queue(&self) -> Option<&'a str> {
        self.dead_letter_queue
    }

    fn dead_letter(&self) -> Result<Option<DeadLetter>> {
        match (self.dead_letter_queue, self.max_receive_count) {
            (Some(queue), Some(max_receive_count)) => {
                Ok(Some(DeadLetter { queue: queue.to_owned(), max_receive_count }))
            }
            (None, None) => Ok(None),
            _ => Err(invalid("DeadLetterQueue and MaxReceiveCount must be given together")),
        }
    }

    /// Checks rules 1 to 3 of `CreateQueue` and fills in defaults.
    pub fn into_new_config(self, name: &str) -> Result<QueueConfig> {
        let fifo = self.fifo.unwrap_or(false);
        if name.ends_with(".fifo") != fifo {
            return Err(Error::new(
                ErrorCode::QueueNameInvalid,
                "the .fifo suffix and the Fifo attribute must agree",
            ));
        }
        let content_based_dedup = self.content_based_dedup.unwrap_or(false);
        if content_based_dedup && !fifo {
            return Err(invalid("ContentBasedDeduplication requires a FIFO queue"));
        }
        Ok(QueueConfig {
            visibility_timeout_secs: self.visibility_timeout_secs.unwrap_or(30),
            delay_secs: self.delay_secs.unwrap_or(0),
            retention_secs: self.retention_secs.unwrap_or(345_600),
            kind: if fifo { QueueKind::Fifo { content_based_dedup } } else { QueueKind::Standard },
            dead_letter: self.dead_letter()?,
        })
    }

    /// Checks rules 1 to 3 of `SetQueueAttributes` and returns the updated config.
    pub fn applied_to(&self, current: &QueueConfig) -> Result<QueueConfig> {
        if self.fifo.is_some() {
            return Err(Error::new(ErrorCode::UnsupportedOperation, "the type of a queue cannot change"));
        }
        let mut kind = current.kind;
        match (&mut kind, self.content_based_dedup) {
            (QueueKind::Standard, Some(true)) => {
                return Err(invalid("ContentBasedDeduplication requires a FIFO queue"));
            }
            (QueueKind::Fifo { content_based_dedup }, Some(value)) => *content_based_dedup = value,
            _ => {}
        }
        let dead_letter = self.dead_letter()?.or_else(|| current.dead_letter.clone());
        Ok(QueueConfig {
            visibility_timeout_secs: self.visibility_timeout_secs.unwrap_or(current.visibility_timeout_secs),
            delay_secs: self.delay_secs.unwrap_or(current.delay_secs),
            retention_secs: self.retention_secs.unwrap_or(current.retention_secs),
            kind,
            dead_letter,
        })
    }
}
EOF
cat > src/request.rs <<'EOF'
use serde_json::Value;

use crate::config::Attributes;
use crate::error::{Error, ErrorCode, Result};
use crate::params::Params;

/// A fully shape- and value-checked command, ready to execute.
#[derive(Debug)]
pub enum Command<'a> {
    CreateQueue { name: &'a str, attributes: Attributes<'a> },
    SetQueueAttributes { queue: &'a str, attributes: Attributes<'a> },
    GetQueueAttributes { queue: &'a str },
    ListQueues { prefix: Option<&'a str> },
    DeleteQueue { queue: &'a str },
    PurgeQueue { queue: &'a str },
    Tick { seconds: u32 },
    SendMessage {
        queue: &'a str,
        body: &'a str,
        delay_secs: Option<u32>,
        group_id: Option<&'a str>,
        deduplication_id: Option<&'a str>,
    },
    ReceiveMessage { queue: &'a str, max_messages: u32, visibility_timeout_secs: Option<u32> },
    DeleteMessage { queue: &'a str, receipt_handle: &'a str },
    ChangeMessageVisibility { queue: &'a str, receipt_handle: &'a str, visibility_timeout_secs: u32 },
}

fn is_name_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '_' || c == '-'
}

fn is_valid_queue_name(name: &str) -> bool {
    let stem = name.strip_suffix(".fifo").unwrap_or(name);
    name.len() <= 80 && !stem.is_empty() && stem.chars().all(is_name_char)
}

fn id_string<'a>(params: &Params<'a>, name: &str) -> Result<Option<&'a str>> {
    let value = params.string(name)?;
    match value {
        Some(id) if id.len() > 128 || id.is_empty() || !id.chars().all(is_name_char) => Err(Error::new(
            ErrorCode::InvalidParameterValue,
            format!("{name} must be 1 to 128 characters from A-Z a-z 0-9 _ -"),
        )),
        _ => Ok(value),
    }
}

impl<'a> Command<'a> {
    pub fn parse(value: &'a Value) -> Result<Self> {
        let invalid_request = |message: &str| Error::new(ErrorCode::InvalidRequest, message);
        let map = value.as_object().ok_or_else(|| invalid_request("the line is not a JSON object"))?;
        let name = map
            .get("Command")
            .and_then(Value::as_str)
            .ok_or_else(|| invalid_request("Command must be a string"))?;
        let p = Params::new(map);
        let attributes = |key: &str| {
            p.object(key)?.map(Attributes::parse).transpose().map(Option::unwrap_or_default)
        };
        Ok(match name {
            "CreateQueue" => {
                p.require(&["QueueName"])?;
                let name = p.required_string("QueueName")?;
                if !is_valid_queue_name(name) {
                    return Err(Error::new(ErrorCode::QueueNameInvalid, "queue name breaks the naming rules"));
                }
                Self::CreateQueue { name, attributes: attributes("Attributes")? }
            }
            "SetQueueAttributes" => {
                p.require(&["QueueName", "Attributes"])?;
                let queue = p.required_string("QueueName")?;
                Self::SetQueueAttributes { queue, attributes: attributes("Attributes")? }
            }
            "GetQueueAttributes" | "DeleteQueue" | "PurgeQueue" => {
                p.require(&["QueueName"])?;
                let queue = p.required_string("QueueName")?;
                match name {
                    "GetQueueAttributes" => Self::GetQueueAttributes { queue },
                    "DeleteQueue" => Self::DeleteQueue { queue },
                    _ => Self::PurgeQueue { queue },
                }
            }
            "ListQueues" => Self::ListQueues { prefix: p.string("Prefix")? },
            "Tick" => {
                p.require(&["Seconds"])?;
                Self::Tick { seconds: p.required_integer("Seconds", 0..=1_209_600)? }
            }
            "SendMessage" => {
                p.require(&["QueueName", "Body"])?;
                let queue = p.required_string("QueueName")?;
                let body = p.required_string("Body")?;
                if body.is_empty() || body.len() > 1024 {
                    return Err(Error::new(ErrorCode::InvalidParameterValue, "Body must be 1 to 1024 bytes"));
                }
                Self::SendMessage {
                    queue,
                    body,
                    delay_secs: p.integer("DelaySeconds", 0..=900)?,
                    group_id: id_string(&p, "GroupId")?,
                    deduplication_id: id_string(&p, "DeduplicationId")?,
                }
            }
            "ReceiveMessage" => {
                p.require(&["QueueName"])?;
                Self::ReceiveMessage {
                    queue: p.required_string("QueueName")?,
                    max_messages: p.integer("MaxMessages", 1..=10)?.unwrap_or(1),
                    visibility_timeout_secs: p.integer("VisibilityTimeout", 0..=43_200)?,
                }
            }
            "DeleteMessage" => {
                p.require(&["QueueName", "ReceiptHandle"])?;
                Self::DeleteMessage {
                    queue: p.required_string("QueueName")?,
                    receipt_handle: p.required_string("ReceiptHandle")?,
                }
            }
            "ChangeMessageVisibility" => {
                p.require(&["QueueName", "ReceiptHandle", "VisibilityTimeout"])?;
                Self::ChangeMessageVisibility {
                    queue: p.required_string("QueueName")?,
                    receipt_handle: p.required_string("ReceiptHandle")?,
                    visibility_timeout_secs: p.required_integer("VisibilityTimeout", 0..=43_200)?,
                }
            }
            _ => return Err(invalid_request("unknown command")),
        })
    }
}
EOF
