use crate::params::Params;

const ATTRIBUTE_NAMES: [&str; 7] = [
    "VisibilityTimeout",
    "DelaySeconds",
    "RetentionSeconds",
    "Fifo",
    "ContentBasedDeduplication",
    "DeadLetterQueue",
    "MaxReceiveCount",
];

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum QueueKind {
    Standard,
    Fifo { content_based_dedup: bool },
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DeadLetter {
    pub queue: String,
    pub max_receive_count: u32,
}

/// The complete, valid attribute set of a queue.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct QueueConfig {
    pub visibility_timeout_secs: u32,
    pub delay_secs: u32,
    pub retention_secs: u32,
    pub kind: QueueKind,
    pub dead_letter: Option<DeadLetter>,
}

/// Attributes as given in a request; every one is optional and individually valid.
#[derive(Debug, Default)]
pub struct Attributes<'a> {
    visibility_timeout_secs: Option<u32>,
    delay_secs: Option<u32>,
    retention_secs: Option<u32>,
    fifo: Option<bool>,
    content_based_dedup: Option<bool>,
    dead_letter_queue: Option<&'a str>,
    max_receive_count: Option<u32>,
}

fn invalid(message: &str) -> Error {
    Error::new(ErrorCode::InvalidParameterValue, message)
}

impl<'a> Attributes<'a> {
    pub fn parse(map: &'a Map<String, Value>) -> Result<Self> {
        let params = Params::new(map);
        if let Some(name) = params.names().find(|name| !ATTRIBUTE_NAMES.contains(name)) {
            return Err(invalid(&format!("unknown attribute {name}")));
        }
        Ok(Self {
            visibility_timeout_secs: params.integer("VisibilityTimeout", 0..=43_200)?,
            delay_secs: params.integer("DelaySeconds", 0..=900)?,
            retention_secs: params.integer("RetentionSeconds", 60..=1_209_600)?,
            fifo: params.boolean("Fifo")?,
            content_based_dedup: params.boolean("ContentBasedDeduplication")?,
            dead_letter_queue: params.string("DeadLetterQueue")?,
            max_receive_count: params.integer("MaxReceiveCount", 1..=1000)?,
        })
    }

    pub fn fifo(&self) -> Option<bool> {
        self.fifo
    }

    pub fn dead_letter_queue(&self) -> Option<&'a str> {
        self.dead_letter_queue
    }

    fn dead_letter(&self) -> Result<Option<DeadLetter>> {
        match (self.dead_letter_queue, self.max_receive_count) {
            (Some(queue), Some(max_receive_count)) => {
                Ok(Some(DeadLetter { queue: queue.to_owned(), max_receive_count }))
            }
            (None, None) => Ok(None),
            _ => Err(invalid("DeadLetterQueue and MaxReceiveCount must be given together")),
        }
    }

    /// Checks rules 1 to 3 of `CreateQueue` and fills in defaults.
    pub fn into_new_config(self, name: &str) -> Result<QueueConfig> {
        let fifo = self.fifo.unwrap_or(false);
        if name.ends_with(".fifo") != fifo {
            return Err(Error::new(
                ErrorCode::QueueNameInvalid,
                "the .fifo suffix and the Fifo attribute must agree",
            ));
        }
        let content_based_dedup = self.content_based_dedup.unwrap_or(false);
        if content_based_dedup && !fifo {
            return Err(invalid("ContentBasedDeduplication requires a FIFO queue"));
        }
        Ok(QueueConfig {
            visibility_timeout_secs: self.visibility_timeout_secs.unwrap_or(30),
            delay_secs: self.delay_secs.unwrap_or(0),
            retention_secs: self.retention_secs.unwrap_or(345_600),
            kind: if fifo { QueueKind::Fifo { content_based_dedup } } else { QueueKind::Standard },
            dead_letter: self.dead_letter()?,
        })
    }

    /// Checks rules 1 to 3 of `SetQueueAttributes` and returns the updated config.
    pub fn applied_to(&self, current: &QueueConfig) -> Result<QueueConfig> {
        if self.fifo.is_some() {
            return Err(Error::new(ErrorCode::UnsupportedOperation, "the type of a queue cannot change"));
        }
        let mut kind = current.kind;
        match (&mut kind, self.content_based_dedup) {
            (QueueKind::Standard, Some(true)) => {
                return Err(invalid("ContentBasedDeduplication requires a FIFO queue"));
            }
            (QueueKind::Fifo { content_based_dedup }, Some(value)) => *content_based_dedup = value,
            _ => {}
        }
        let dead_letter = self.dead_letter()?.or_else(|| current.dead_letter.clone());
        Ok(QueueConfig {
            visibility_timeout_secs: self.visibility_timeout_secs.unwrap_or(current.visibility_timeout_secs),
            delay_secs: self.delay_secs.unwrap_or(current.delay_secs),
            retention_secs: self.retention_secs.unwrap_or(current.retention_secs),
            kind,
            dead_letter,
        })
    }
}
EOF
