use serde_json::Value;

use crate::config::Attributes;
use crate::error::{Error, ErrorCode, Result};
use crate::params::Params;

/// A fully shape- and value-checked command, ready to execute.
#[derive(Debug)]
pub enum Command<'a> {
    CreateQueue { name: &'a str, attributes: Attributes<'a> },
    SetQueueAttributes { queue: &'a str, attributes: Attributes<'a> },
    GetQueueAttributes { queue: &'a str },
    ListQueues { prefix: Option<&'a str> },
    DeleteQueue { queue: &'a str },
    PurgeQueue { queue: &'a str },
    Tick { seconds: u32 },
    SendMessage {
        queue: &'a str,
        body: &'a str,
        delay_secs: Option<u32>,
        group_id: Option<&'a str>,
        deduplication_id: Option<&'a str>,
    },
    ReceiveMessage { queue: &'a str, max_messages: u32, visibility_timeout_secs: Option<u32> },
    DeleteMessage { queue: &'a str, receipt_handle: &'a str },
    ChangeMessageVisibility { queue: &'a str, receipt_handle: &'a str, visibility_timeout_secs: u32 },
}

fn is_name_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '_' || c == '-'
}

fn is_valid_queue_name(name: &str) -> bool {
    let stem = name.strip_suffix(".fifo").unwrap_or(name);
    name.len() <= 80 && !stem.is_empty() && stem.chars().all(is_name_char)
}

fn id_string<'a>(params: &Params<'a>, name: &str) -> Result<Option<&'a str>> {
    let value = params.string(name)?;
    match value {
        Some(id) if id.len() > 128 || id.is_empty() || !id.chars().all(is_name_char) => Err(Error::new(
            ErrorCode::InvalidParameterValue,
            format!("{name} must be 1 to 128 characters from A-Z a-z 0-9 _ -"),
        )),
        _ => Ok(value),
    }
}

impl<'a> Command<'a> {
    pub fn parse(value: &'a Value) -> Result<Self> {
        let invalid_request = |message: &str| Error::new(ErrorCode::InvalidRequest, message);
        let map = value.as_object().ok_or_else(|| invalid_request("the line is not a JSON object"))?;
        let name = map
            .get("Command")
            .and_then(Value::as_str)
            .ok_or_else(|| invalid_request("Command must be a string"))?;
        let p = Params::new(map);
        let attributes = |key: &str| {
            p.object(key)?.map(Attributes::parse).transpose().map(Option::unwrap_or_default)
        };
        Ok(match name {
            "CreateQueue" => {
                p.require(&["QueueName"])?;
                let name = p.required_string("QueueName")?;
                if !is_valid_queue_name(name) {
                    return Err(Error::new(ErrorCode::QueueNameInvalid, "queue name breaks the naming rules"));
                }
                Self::CreateQueue { name, attributes: attributes("Attributes")? }
            }
            "SetQueueAttributes" => {
                p.require(&["QueueName", "Attributes"])?;
                let queue = p.required_string("QueueName")?;
                Self::SetQueueAttributes { queue, attributes: attributes("Attributes")? }
            }
            "GetQueueAttributes" | "DeleteQueue" | "PurgeQueue" => {
                p.require(&["QueueName"])?;
                let queue = p.required_string("QueueName")?;
                match name {
                    "GetQueueAttributes" => Self::GetQueueAttributes { queue },
                    "DeleteQueue" => Self::DeleteQueue { queue },
                    _ => Self::PurgeQueue { queue },
                }
            }
            "ListQueues" => Self::ListQueues { prefix: p.string("Prefix")? },
            "Tick" => {
                p.require(&["Seconds"])?;
                Self::Tick { seconds: p.required_integer("Seconds", 0..=1_209_600)? }
            }
            "SendMessage" => {
                p.require(&["QueueName", "Body"])?;
                let queue = p.required_string("QueueName")?;
                let body = p.required_string("Body")?;
                if body.is_empty() || body.len() > 1024 {
                    return Err(Error::new(ErrorCode::InvalidParameterValue, "Body must be 1 to 1024 bytes"));
                }
                Self::SendMessage {
                    queue,
                    body,
                    delay_secs: p.integer("DelaySeconds", 0..=900)?,
                    group_id: id_string(&p, "GroupId")?,
                    deduplication_id: id_string(&p, "DeduplicationId")?,
                }
            }
            "ReceiveMessage" => {
                p.require(&["QueueName"])?;
                Self::ReceiveMessage {
                    queue: p.required_string("QueueName")?,
                    max_messages: p.integer("MaxMessages", 1..=10)?.unwrap_or(1),
                    visibility_timeout_secs: p.integer("VisibilityTimeout", 0..=43_200)?,
                }
            }
            "DeleteMessage" => {
                p.require(&["QueueName", "ReceiptHandle"])?;
                Self::DeleteMessage {
                    queue: p.required_string("QueueName")?,
                    receipt_handle: p.required_string("ReceiptHandle")?,
                }
            }
            "ChangeMessageVisibility" => {
                p.require(&["QueueName", "ReceiptHandle", "VisibilityTimeout"])?;
                Self::ChangeMessageVisibility {
                    queue: p.required_string("QueueName")?,
                    receipt_handle: p.required_string("ReceiptHandle")?,
                    visibility_timeout_secs: p.required_integer("VisibilityTimeout", 0..=43_200)?,
                }
            }
            _ => return Err(invalid_request("unknown command")),
        })
    }
}
