use std::collections::{BTreeMap, BTreeSet, HashMap, HashSet};
use std::fmt;

use crate::config::{QueueConfig, QueueKind};

pub const MAX_MESSAGES: usize = 100_000;
const DEDUP_WINDOW_SECS: u64 = 300;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct MessageId(pub u64);

impl fmt::Display for MessageId {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "m-{}", self.0)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct ReceiptHandle(pub u64);

impl fmt::Display for ReceiptHandle {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "r-{}", self.0)
    }
}

impl ReceiptHandle {
    /// Parses the canonical text form only: `r-` and a number without sign or leading zeros.
    pub fn parse(text: &str) -> Option<Self> {
        let number = text.strip_prefix("r-")?;
        let n: u64 = number.parse().ok()?;
        (n.to_string() == number).then_some(Self(n))
    }
}

#[derive(Debug, Clone, Copy)]
enum Hold {
    Delayed { until: u64 },
    InFlight { until: u64, handle: ReceiptHandle },
}

#[derive(Debug)]
pub struct Message {
    pub id: MessageId,
    pub body: String,
    pub sent_at: u64,
    receive_count: u32,
    first_received_at: Option<u64>,
    group_id: Option<String>,
    sequence: Option<u64>,
    hold: Hold,
}

impl Message {
    pub fn new(id: MessageId, body: &str, now: u64, delay_secs: u32, group_id: Option<&str>) -> Self {
        Self {
            id,
            body: body.to_owned(),
            sent_at: now,
            receive_count: 0,
            first_received_at: None,
            group_id: group_id.map(str::to_owned),
            sequence: None,
            hold: Hold::Delayed { until: now + u64::from(delay_secs) },
        }
    }

    /// The state a message has when it arrives in a dead-letter queue.
    pub fn reset_for_dead_letter(&mut self, now: u64) {
        self.receive_count = 0;
        self.first_received_at = None;
        self.hold = Hold::Delayed { until: now };
    }

    fn state(&self, now: u64) -> State {
        match self.hold {
            Hold::Delayed { until } if now < until => State::Delayed,
            Hold::InFlight { until, .. } if now < until => State::InFlight,
            _ => State::Visible,
        }
    }
}

#[derive(Debug, PartialEq, Eq)]
enum State {
    Visible,
    InFlight,
    Delayed,
}

#[derive(Debug, Default, PartialEq, Eq)]
pub struct Counts {
    pub visible: usize,
    pub in_flight: usize,
    pub delayed: usize,
}

/// A message handed to a consumer by `Queue::receive`.
pub struct Delivery {
    pub id: MessageId,
    pub handle: ReceiptHandle,
    pub body: String,
    pub receive_count: u32,
    pub sent_at: u64,
    pub first_received_at: u64,
    pub group_id: Option<String>,
    pub sequence: Option<u64>,
}

#[derive(Default)]
pub struct Received {
    pub delivered: Vec<Delivery>,
    pub dead: Vec<Message>,
}

#[derive(Debug, Clone, Copy)]
pub struct Original {
    pub id: MessageId,
    pub sequence: Option<u64>,
}

struct DedupEntry {
    at: u64,
    original: Original,
}

pub struct Queue {
    pub config: QueueConfig,
    /// Messages by arrival key, which grows with every message added.
    messages: BTreeMap<u64, Message>,
    next_key: u64,
    by_age: BTreeSet<(u64, u64)>,
    /// Latest receipt handle of each in-flight message, mapped to its arrival key.
    handles: HashMap<ReceiptHandle, u64>,
    dedup: HashMap<String, DedupEntry>,
    next_sequence: u64,
}

impl Queue {
    pub fn new(config: QueueConfig) -> Self {
        Self {
            config,
            messages: BTreeMap::new(),
            next_key: 0,
            by_age: BTreeSet::new(),
            handles: HashMap::new(),
            dedup: HashMap::new(),
            next_sequence: 1,
        }
    }

    pub fn is_fifo(&self) -> bool {
        matches!(self.config.kind, QueueKind::Fifo { .. })
    }

    pub fn len(&self) -> usize {
        self.messages.len()
    }

    /// Removes every message that retention has expired at `now`.
    pub fn expire(&mut self, now: u64) {
        let retention = u64::from(self.config.retention_secs);
        while let Some(&(sent_at, key)) = self.by_age.first() {
            if sent_at + retention > now {
                break;
            }
            self.remove(key);
        }
    }

    fn remove(&mut self, key: u64) -> Option<Message> {
        let message = self.messages.remove(&key)?;
        self.by_age.remove(&(message.sent_at, key));
        if let Hold::InFlight { handle, .. } = message.hold {
            self.handles.remove(&handle);
        }
        Some(message)
    }

    /// Appends a message and returns its sequence number on a FIFO queue.
    pub fn add(&mut self, mut message: Message) -> Option<u64> {
        let sequence = self.is_fifo().then(|| {
            let sequence = self.next_sequence;
            self.next_sequence += 1;
            sequence
        });
        message.sequence = sequence;
        self.by_age.insert((message.sent_at, self.next_key));
        self.messages.insert(self.next_key, message);
        self.next_key += 1;
        sequence
    }

    pub fn purge(&mut self) {
        self.messages.clear();
        self.by_age.clear();
        self.handles.clear();
    }

    pub fn counts(&self, now: u64) -> Counts {
        self.messages.values().fold(Counts::default(), |mut counts, m| {
            match m.state(now) {
                State::Visible => counts.visible += 1,
                State::InFlight => counts.in_flight += 1,
                State::Delayed => counts.delayed += 1,
            }
            counts
        })
    }

    /// The original of a duplicate FIFO send, if `key` was accepted within the window.
    pub fn duplicate_of(&self, key: &str, now: u64) -> Option<Original> {
        let entry = self.dedup.get(key)?;
        (now - entry.at < DEDUP_WINDOW_SECS).then_some(entry.original)
    }

    pub fn record_dedup(&mut self, key: &str, now: u64, original: Original) {
        self.dedup.insert(key.to_owned(), DedupEntry { at: now, original });
    }

    pub fn receive(
        &mut self,
        now: u64,
        max_messages: usize,
        visibility_timeout_secs: u32,
        next_handle: &mut u64,
    ) -> Received {
        let max_receive_count = self.config.dead_letter.as_ref().map(|d| d.max_receive_count);
        let mut received = Received::default();
        let mut seen_groups: HashSet<String> = HashSet::new();
        let mut cursor = 0;
        while received.delivered.len() < max_messages {
            let Some((&key, message)) = self.messages.range_mut(cursor..).next() else {
                break;
            };
            cursor = key + 1;
            if message.group_id.as_ref().is_some_and(|g| seen_groups.contains(g)) {
                continue;
            }
            let mut stays = true;
            if message.state(now) != State::Visible {
            } else if max_receive_count.is_some_and(|max| message.receive_count >= max) {
                stays = false;
            } else {
                let handle = ReceiptHandle(*next_handle);
                *next_handle += 1;
                if let Hold::InFlight { handle: old, .. } = message.hold {
                    self.handles.remove(&old);
                }
                message.hold = Hold::InFlight { until: now + u64::from(visibility_timeout_secs), handle };
                message.receive_count += 1;
                let first_received_at = *message.first_received_at.get_or_insert(now);
                self.handles.insert(handle, key);
                received.delivered.push(Delivery {
                    id: message.id,
                    handle,
                    body: message.body.clone(),
                    receive_count: message.receive_count,
                    sent_at: message.sent_at,
                    first_received_at,
                    group_id: message.group_id.clone(),
                    sequence: message.sequence,
                });
            }
            if stays {
                if let Some(group) = &message.group_id {
                    seen_groups.insert(group.clone());
                }
            } else if let Some(dead) = self.remove(key) {
                received.dead.push(dead);
            }
        }
        received
    }

    /// The arrival key of the message that `handle` is the latest handle of, if it is in flight.
    fn in_flight_key(&self, handle: ReceiptHandle, now: u64) -> Option<u64> {
        let key = *self.handles.get(&handle)?;
        (self.messages.get(&key)?.state(now) == State::InFlight).then_some(key)
    }

    /// Deletes the in-flight message of `handle`; false if the handle is not usable.
    pub fn delete(&mut self, handle: ReceiptHandle, now: u64) -> bool {
        self.in_flight_key(handle, now).is_some_and(|key| self.remove(key).is_some())
    }

    /// Moves the end of the in-flight window of `handle`; false if the handle is not usable.
    pub fn change_visibility(&mut self, handle: ReceiptHandle, now: u64, timeout_secs: u32) -> bool {
        let Some(key) = self.in_flight_key(handle, now) else {
            return false;
        };
        self.messages.get_mut(&key).is_some_and(|message| {
            message.hold = Hold::InFlight { until: now + u64::from(timeout_secs), handle };
            true
        })
    }
}
