use std::collections::HashMap;

use serde_json::{Map, Value, json};

use crate::config::{QueueConfig, QueueKind};
use crate::error::{Error, ErrorCode, Result};
use crate::queue::{Delivery, MAX_MESSAGES, Message, MessageId, Original, Queue, ReceiptHandle};
use crate::request::Command;

const MAX_QUEUES: usize = 1000;

type Fields = Map<String, Value>;

fn fields<const N: usize>(pairs: [(&str, Value); N]) -> Fields {
    pairs.into_iter().map(|(k, v)| (k.to_owned(), v)).collect()
}

/// All state of the process: the clock, the queues and the identifier counters.
pub struct Service {
    now: u64,
    queues: HashMap<String, Queue>,
    next_message: u64,
    next_handle: u64,
}

impl Default for Service {
    fn default() -> Self {
        Self { now: 0, queues: HashMap::new(), next_message: 1, next_handle: 1 }
    }
}

fn error_response(error: &Error) -> Value {
    json!({"ok": false, "error": {"code": error.code().as_str(), "message": error.message()}})
}

impl Service {
    /// Runs one input line and returns the response object.
    pub fn handle_line(&mut self, line: &[u8]) -> Value {
        let result = serde_json::from_slice::<Value>(line)
            .map_err(|e| Error::new(ErrorCode::InvalidRequest, format!("invalid JSON: {e}")))
            .and_then(|value| Command::parse(&value).and_then(|command| self.execute(command)));
        match result {
            Ok(mut result) => {
                result.insert("ok".to_owned(), Value::Bool(true));
                Value::Object(result)
            }
            Err(error) => error_response(&error),
        }
    }

    fn queue(&mut self, name: &str) -> Result<&mut Queue> {
        let now = self.now;
        let queue = self
            .queues
            .get_mut(name)
            .ok_or_else(|| Error::new(ErrorCode::QueueDoesNotExist, format!("no queue named {name}")))?;
        queue.expire(now);
        Ok(queue)
    }

    fn execute(&mut self, command: Command<'_>) -> Result<Fields> {
        match command {
            Command::CreateQueue { name, attributes } => {
                let dead_letter_name = attributes.dead_letter_queue();
                let config = attributes.into_new_config(name)?;
                if let Some(existing) = self.queues.get(name) {
                    return if existing.config == config {
                        Ok(Fields::new())
                    } else {
                        Err(Error::new(ErrorCode::QueueAlreadyExists, "queue exists with other attributes"))
                    };
                }
                if let Some(dead_letter_name) = dead_letter_name {
                    self.check_dead_letter_target(dead_letter_name, config.kind)?;
                }
                if self.queues.len() >= MAX_QUEUES {
                    return Err(Error::new(ErrorCode::LimitExceeded, "1000 queues exist"));
                }
                self.queues.insert(name.to_owned(), Queue::new(config));
                Ok(Fields::new())
            }
            Command::SetQueueAttributes { queue, attributes } => {
                let current = self.queue(queue)?.config.clone();
                let config = attributes.applied_to(&current)?;
                if let Some(target) = attributes.dead_letter_queue() {
                    if target == queue {
                        return Err(Error::new(ErrorCode::InvalidParameterValue, "a queue cannot be its own dead-letter queue"));
                    }
                    self.check_dead_letter_target(target, config.kind)?;
                }
                let now = self.now;
                let target = self.queue(queue)?;
                target.config = config;
                target.expire(now);
                Ok(Fields::new())
            }
            Command::GetQueueAttributes { queue } => {
                let now = self.now;
                let queue = self.queue(queue)?;
                let counts = queue.counts(now);
                Ok(fields([
                    ("Attributes", attributes_json(&queue.config)),
                    (
                        "Counts",
                        json!({"Visible": counts.visible, "InFlight": counts.in_flight, "Delayed": counts.delayed}),
                    ),
                ]))
            }
            Command::ListQueues { prefix } => {
                let mut names: Vec<&str> = self
                    .queues
                    .keys()
                    .map(String::as_str)
                    .filter(|name| prefix.is_none_or(|p| name.starts_with(p)))
                    .collect();
                names.sort_unstable();
                Ok(fields([("QueueNames", json!(names))]))
            }
            Command::DeleteQueue { queue } => {
                self.queue(queue)?;
                self.queues.remove(queue);
                for other in self.queues.values_mut() {
                    if other.config.dead_letter.as_ref().is_some_and(|d| d.queue == queue) {
                        other.config.dead_letter = None;
                    }
                }
                Ok(Fields::new())
            }
            Command::PurgeQueue { queue } => {
                self.queue(queue)?.purge();
                Ok(Fields::new())
            }
            Command::Tick { seconds } => {
                self.now += u64::from(seconds);
                Ok(fields([("Now", json!(self.now))]))
            }
            Command::SendMessage { queue, body, delay_secs, group_id, deduplication_id } => {
                self.send(queue, body, delay_secs, group_id, deduplication_id)
            }
            Command::ReceiveMessage { queue, max_messages, visibility_timeout_secs } => {
                let (now, handles) = (self.now, &mut self.next_handle);
                let target = self.queues.get_mut(queue);
                let target = target.ok_or_else(|| Error::new(ErrorCode::QueueDoesNotExist, format!("no queue named {queue}")))?;
                target.expire(now);
                let timeout = visibility_timeout_secs.unwrap_or(target.config.visibility_timeout_secs);
                let dead_letter = target.config.dead_letter.as_ref().map(|d| d.queue.clone());
                let received = target.receive(now, max_messages as usize, timeout, handles);
                if let Some(name) = dead_letter {
                    let dead_queue = self
                        .queues
                        .get_mut(&name)
                        .expect("a dead-letter target exists: DeleteQueue clears references to it");
                    for mut message in received.dead {
                        message.reset_for_dead_letter(now);
                        dead_queue.add(message);
                    }
                    dead_queue.expire(now);
                }
                let messages: Vec<Value> = received.delivered.iter().map(delivery_json).collect();
                Ok(fields([("Messages", Value::Array(messages))]))
            }
            Command::DeleteMessage { queue, receipt_handle } => {
                let handle = self.issued_handle(receipt_handle)?;
                let now = self.now;
                if self.queue(queue)?.delete(handle, now) {
                    Ok(Fields::new())
                } else {
                    Err(expired())
                }
            }
            Command::ChangeMessageVisibility { queue, receipt_handle, visibility_timeout_secs } => {
                let handle = self.issued_handle(receipt_handle)?;
                let now = self.now;
                if self.queue(queue)?.change_visibility(handle, now, visibility_timeout_secs) {
                    Ok(Fields::new())
                } else {
                    Err(expired())
                }
            }
        }
    }

    fn issued_handle(&self, text: &str) -> Result<ReceiptHandle> {
        ReceiptHandle::parse(text)
            .filter(|handle| handle.0 < self.next_handle)
            .ok_or_else(|| Error::new(ErrorCode::ReceiptHandleInvalid, "receipt handle was never issued"))
    }

    fn check_dead_letter_target(&self, name: &str, kind: QueueKind) -> Result<()> {
        let target = self
            .queues
            .get(name)
            .ok_or_else(|| Error::new(ErrorCode::QueueDoesNotExist, format!("no dead-letter queue named {name}")))?;
        if target.is_fifo() != matches!(kind, QueueKind::Fifo { .. }) {
            return Err(Error::new(ErrorCode::InvalidParameterValue, "dead-letter queue type differs"));
        }
        Ok(())
    }

    fn send(
        &mut self,
        queue: &str,
        body: &str,
        delay_secs: Option<u32>,
        group_id: Option<&str>,
        deduplication_id: Option<&str>,
    ) -> Result<Fields> {
        let now = self.now;
        let next_message = self.next_message;
        let target = self.queue(queue)?;
        let unsupported = |what: &str| Error::new(ErrorCode::UnsupportedOperation, what.to_owned());
        let missing = |what: &str| Error::new(ErrorCode::MissingParameter, format!("{what} is required"));
        let mut dedup_key = None;
        match target.config.kind {
            QueueKind::Standard if group_id.is_some() || deduplication_id.is_some() => {
                return Err(unsupported("GroupId and DeduplicationId need a FIFO queue"));
            }
            QueueKind::Fifo { .. } if delay_secs.is_some() => {
                return Err(unsupported("DelaySeconds per message is not supported on a FIFO queue"));
            }
            QueueKind::Fifo { content_based_dedup } => {
                if group_id.is_none() {
                    return Err(missing("GroupId"));
                }
                dedup_key = Some(match (deduplication_id, content_based_dedup) {
                    (Some(id), _) => id,
                    (None, true) => body,
                    (None, false) => return Err(missing("DeduplicationId")),
                });
            }
            QueueKind::Standard => {}
        }
        if let Some(original) = dedup_key.and_then(|key| target.duplicate_of(key, now)) {
            return Ok(send_result(original));
        }
        if target.len() >= MAX_MESSAGES {
            return Err(Error::new(ErrorCode::LimitExceeded, "queue holds 100000 messages"));
        }
        let delay = delay_secs.unwrap_or(target.config.delay_secs);
        let id = MessageId(next_message);
        let sequence = target.add(Message::new(id, body, now, delay, group_id));
        if let Some(key) = dedup_key {
            target.record_dedup(key, now, Original { id, sequence });
        }
        self.next_message += 1;
        Ok(send_result(Original { id, sequence }))
    }
}

fn expired() -> Error {
    Error::new(ErrorCode::ReceiptHandleExpired, "receipt handle is not the latest handle of an in-flight message")
}

fn send_result(original: Original) -> Fields {
    let mut result = fields([("MessageId", json!(original.id.to_string()))]);
    if let Some(sequence) = original.sequence {
        result.insert("SequenceNumber".to_owned(), json!(sequence));
    }
    result
}

fn attributes_json(config: &QueueConfig) -> Value {
    let (fifo, content_based_dedup) = match config.kind {
        QueueKind::Standard => (false, false),
        QueueKind::Fifo { content_based_dedup } => (true, content_based_dedup),
    };
    let mut attributes = json!({
        "VisibilityTimeout": config.visibility_timeout_secs,
        "DelaySeconds": config.delay_secs,
        "RetentionSeconds": config.retention_secs,
        "Fifo": fifo,
        "ContentBasedDeduplication": content_based_dedup,
    });
    if let Some(dead_letter) = &config.dead_letter {
        attributes["DeadLetterQueue"] = json!(dead_letter.queue);
        attributes["MaxReceiveCount"] = json!(dead_letter.max_receive_count);
    }
    attributes
}

fn delivery_json(delivery: &Delivery) -> Value {
    let mut message = json!({
        "MessageId": delivery.id.to_string(),
        "ReceiptHandle": delivery.handle.to_string(),
        "Body": delivery.body,
        "ReceiveCount": delivery.receive_count,
        "SentAt": delivery.sent_at,
        "FirstReceivedAt": delivery.first_received_at,
    });
    if let (Some(group), Some(sequence)) = (&delivery.group_id, delivery.sequence) {
        message["GroupId"] = json!(group);
        message["SequenceNumber"] = json!(sequence);
    }
    message
}
