        .lines()
        .map(|l| serde_json::from_str(l).expect("each response is JSON"))
        .collect()
}

#[test]
fn send_receive_delete_and_visibility_timeout() {
    let out = session(concat!(
        "{\"Command\":\"CreateQueue\",\"QueueName\":\"jobs\"}\n",
        "{\"Command\":\"SendMessage\",\"QueueName\":\"jobs\",\"Body\":\"a\"}\n",
        "{\"Command\":\"ReceiveMessage\",\"QueueName\":\"jobs\"}\n",
        "{\"Command\":\"Tick\",\"Seconds\":30}\n",
        "{\"Command\":\"DeleteMessage\",\"QueueName\":\"jobs\",\"ReceiptHandle\":\"r-1\"}\n",
        "{\"Command\":\"DeleteMessage\",\"QueueName\":\"jobs\",\"ReceiptHandle\":\"r-01\"}",
    ));
    assert_eq!(
        out,
        vec![
            json!({"ok": true}),
            json!({"ok": true, "MessageId": "m-1"}),
            json!({"ok": true, "Messages": [{"MessageId": "m-1", "ReceiptHandle": "r-1",
                "Body": "a", "ReceiveCount": 1, "SentAt": 0, "FirstReceivedAt": 0}]}),
            json!({"ok": true, "Now": 30}),
            json!({"ok": false, "error": {"code": "ReceiptHandleExpired", "message": out[4]["error"]["message"]}}),
            json!({"ok": false, "error": {"code": "ReceiptHandleInvalid", "message": out[5]["error"]["message"]}}),
        ]
    );
}

#[test]
fn bad_lines_each_get_one_invalid_request() {
    let out = session("\n[1]\n{\"Command\":\"Nope\"}\n");
    let codes: Vec<&Value> = out.iter().map(|r| &r["error"]["code"]).collect();
    assert_eq!(codes, vec!["InvalidRequest"; 3]);
}
